// DeleteUniqueIndexCache 删除索引存在的缓存
func (e *EvaluationTemplateRepo) DeleteIndexCache(ctx context.Context, data ...*yanxue_model.EvaluationTemplate) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, e.cache.Key(CacheEvaluationTemplateByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[e.cache.Key(CacheEvaluationTemplateByIDPrefix, item.ID)] = struct{}{}
			KeyMap[e.cache.Key(CacheEvaluationTemplateByTemplateNamePrefix, item.TemplateName)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := e.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
